### Step 4: Weighted file adjacency builder

In `src/components.rs`, build a weighted undirected adjacency from the raw ref data. Reuses `db.all_resolved_refs()` and `db.all_symbol_file_map()` but counts edges instead of deduplicating into HashSet.

```rust
use std::collections::HashMap;
use crate::db::{Db, FileRow};
use crate::error::Result;

type WeightedAdj = HashMap<i64, Vec<(i64, f64)>>;

fn build_weighted_adjacency(files: &[FileRow], db: &Db) -> Result<WeightedAdj> {
    let sym_to_file: HashMap<i64, i64> = db.all_symbol_file_map()?.into_iter().collect();
    let refs = db.all_resolved_refs()?;

    // Count directed refs per (src, dst) pair
    let mut directed: HashMap<(i64, i64), usize> = HashMap::new();
    for (src_file, target_sym) in &refs {
        if let Some(&target_file) = sym_to_file.get(target_sym) {
            if *src_file != target_file {
                *directed.entry((*src_file, target_file)).or_default() += 1;
            }
        }
    }

    // Symmetrize into undirected with canonical (min, max) keys
    let mut undirected: HashMap<(i64, i64), f64> = HashMap::new();
    for (&(a, b), &count) in &directed {
        let key = if a < b { (a, b) } else { (b, a) };
        // weight = sum of (1/ambiguity) per ref; ambiguity=1 for all resolved refs
        *undirected.entry(key).or_default() += count as f64;
    }

    // Build adjacency list
    let mut adj: WeightedAdj = files.iter().map(|f| (f.id, Vec::new())).collect();
    for (&(a, b), &w) in &undirected {
        adj.entry(a).or_default().push((b, w));
        adj.entry(b).or_default().push((a, w));
    }
    Ok(adj)
}
```

### Step 5: Louvain community detection

Standard Louvain with resolution parameter γ, in `src/components.rs`. Operates on dense-indexed nodes internally, maps back to file IDs on return.

```rust
pub struct LouvainResult {
    pub communities: HashMap<i64, usize>,  // file_id -> community_id
    pub modularity: f64,
    pub resolution: f64,
}

fn louvain(adj: &WeightedAdj, resolution: f64) -> LouvainResult {
    let nodes: Vec<i64> = adj.keys().copied().collect();
    let n = nodes.len();
    let id_to_idx: HashMap<i64, usize> = nodes.iter().enumerate().map(|(i, &id)| (id, i)).collect();

    // Build dense adjacency + compute total weight
    let mut neighbors: Vec<Vec<(usize, f64)>> = vec![Vec::new(); n];
    let mut total_weight = 0.0;
    for (&node, edges) in adj {
        let i = id_to_idx[&node];
        for &(nbr, w) in edges {
            if let Some(&j) = id_to_idx.get(&nbr) {
                neighbors[i].push((j, w));
                total_weight += w;
            }
        }
    }
    total_weight /= 2.0; // each edge counted twice in undirected

    // Initialize: each node in its own community
    let mut community: Vec<usize> = (0..n).collect();
    let mut k: Vec<f64> = vec![0.0; n]; // weighted degree
    for i in 0..n {
        k[i] = neighbors[i].iter().map(|(_, w)| w).sum();
    }

    // Phase 1: local moves until convergence
    let m2 = 2.0 * total_weight;
    let mut improved = true;
    while improved {
        improved = false;
        for i in 0..n {
            let current_comm = community[i];
            // Compute weights to each neighboring community
            let mut comm_weights: HashMap<usize, f64> = HashMap::new();
            for &(j, w) in &neighbors[i] {
                *comm_weights.entry(community[j]).or_default() += w;
            }
            // Sum of degrees in each community
            let mut sigma_tot: HashMap<usize, f64> = HashMap::new();
            for j in 0..n {
                *sigma_tot.entry(community[j]).or_default() += k[j];
            }
            // Remove i from current community for comparison
            let ki_in_current = comm_weights.get(&current_comm).copied().unwrap_or(0.0);
            let sigma_current = sigma_tot[&current_comm] - k[i];

            let mut best_comm = current_comm;
            let mut best_gain = 0.0;
            for (&c, &ki_in) in &comm_weights {
                if c == current_comm { continue; }
                let sigma_c = sigma_tot[&c];
                let gain = (ki_in - ki_in_current) / m2
                    - resolution * k[i] * (sigma_c - sigma_current) / (m2 * m2);
                if gain > best_gain {
                    best_gain = gain;
                    best_comm = c;
                }
            }
            if best_comm != current_comm {
                community[i] = best_comm;
                improved = true;
            }
        }
    }

    // Compute modularity
    let mut q = 0.0;
    for i in 0..n {
        for &(j, w) in &neighbors[i] {
            if community[i] == community[j] {
                q += w - resolution * k[i] * k[j] / m2;
            }
        }
    }
    q /= m2;

    // Renumber communities to 0..k
    let mut remap: HashMap<usize, usize> = HashMap::new();
    let mut next = 0;
    let communities = nodes.iter().map(|&id| {
        let c = community[id_to_idx[&id]];
        let mapped = *remap.entry(c).or_insert_with(|| { let v = next; next += 1; v });
        (id, mapped)
    }).collect();

    LouvainResult { communities, modularity: q, resolution }
}
```

Note: this is a single-level Louvain (no aggregation phase). For the file-level graph (typically 10s-100s of nodes), single-level is sufficient and simpler. The aggregation phase (hierarchical Louvain) is an optimization for graphs with thousands+ of nodes — can be added later if needed.

### Step 6: Resolution auto-tuning

In `src/components.rs`. Try a set of candidate γ values, filter degenerate results, pick highest modularity.

```rust
fn auto_tune(adj: &WeightedAdj) -> LouvainResult {
    let n = adj.len();
    let candidates = [0.5, 0.75, 1.0, 1.25, 1.5, 2.0];

    let results: Vec<LouvainResult> = candidates.iter()
        .map(|&gamma| louvain(adj, gamma))
        .collect();

    // Filter: must have ≥2 communities, largest must be <50% of nodes
    let viable: Vec<&LouvainResult> = results.iter().filter(|r| {
        let mut sizes: HashMap<usize, usize> = HashMap::new();
        for &c in r.communities.values() { *sizes.entry(c).or_default() += 1; }
        let k = sizes.len();
        let max_size = sizes.values().max().copied().unwrap_or(0);
        k >= 2 && (max_size as f64) < 0.5 * n as f64
    }).collect();

    if let Some(best) = viable.iter().max_by(|a, b| a.modularity.partial_cmp(&b.modularity).unwrap()) {
        // Clone the best result (re-run to own it, or store by value above)
        louvain(adj, best.resolution)
    } else {
        // All degenerate — fall back to γ=1.0
        results.into_iter().find(|r| r.resolution == 1.0).unwrap()
    }
}
```

