### Step 8: Auto-naming — longest common path prefix

In `src/components.rs`. Given the file paths in a cluster, extract a human-readable name from their shared path structure.

```rust
fn auto_name(paths: &[&str]) -> String {
    if paths.is_empty() { return \"unknown\".to_string(); }
    if paths.len() == 1 {
        // Single file: use parent dir name or file stem
        return Path::new(paths[0])
            .parent()
            .and_then(|p| p.file_name())
            .map(|s| s.to_string_lossy().to_string())
            .unwrap_or_else(|| \"root\".to_string());
    }

    // Split all paths into components
    let parts: Vec<Vec<&str>> = paths.iter()
        .map(|p| p.split('/').collect::<Vec<_>>())
        .collect();

    // Find longest common prefix (excluding file name)
    let min_len = parts.iter().map(|p| p.len().saturating_sub(1)).min().unwrap_or(0);
    let mut prefix_len = 0;
    for i in 0..min_len {
        if parts.iter().all(|p| p[i] == parts[0][i]) {
            prefix_len = i + 1;
        } else {
            break;
        }
    }

    if prefix_len == 0 {
        \"root\".to_string()
    } else {
        parts[0][prefix_len - 1].to_string()
    }
}
```

Example outputs: files in `src/db/*.rs` → \"db\", files in `src/tools/*.rs` → \"tools\", files spanning `src/` → \"src\" or \"root\".

### Step 9: Discovery orchestration

In `src/components.rs`, the main entry point called from the pipeline:

```rust
use uuid::Uuid;

pub fn discover_components(db: &Db, files: &[FileRow], workspace_root: &Path) -> Result<usize> {
    if files.is_empty() { return Ok(0); }

    // First-run gate: only populate if no components exist yet
    if db.component_count()? > 0 {
        // Reconciliation is sutra/46 — skip for now
        return Ok(0);
    }

    let config = load_config(workspace_root)?;
    let adj = build_weighted_adjacency(files, db)?;

    // Skip if graph has no edges (nothing to cluster)
    let has_edges = adj.values().any(|nbrs| !nbrs.is_empty());
    if !has_edges { return Ok(0); }

    let result = if let Some(gamma) = config.resolution {
        louvain(&adj, gamma)
    } else {
        auto_tune(&adj)
    };

    // Group files by community
    let file_map: HashMap<i64, &FileRow> = files.iter().map(|f| (f.id, f)).collect();
    let mut clusters: HashMap<usize, Vec<i64>> = HashMap::new();
    for (&file_id, &comm) in &result.communities {
        clusters.entry(comm).or_default().push(file_id);
    }

    // Create components and membership
    let mut membership_rows = Vec::new();
    for (_, file_ids) in &clusters {
        let paths: Vec<&str> = file_ids.iter()
            .filter_map(|id| file_map.get(id).map(|f| f.path.as_str()))
            .collect();
        let name = auto_name(&paths);
        let id = Uuid::now_v7().to_string();

        db.insert_component(&id, &name)?;
        for &fid in file_ids {
            membership_rows.push((id.clone(), fid));
        }
    }
    db.batch_insert_membership(&membership_rows)?;

    Ok(clusters.len())
}
```

